import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { Resend } from 'resend';

if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const resend = new Resend(process.env.RESEND_API_KEY);
// Resend's quickstart send from its testing domain to the account's own address, with the fields Dub sends
const email = {
  from: 'Dub <onboarding@resend.dev>',
  to: ['delivered@resend.dev'],
  subject: 'Your Dub login code',
  text: 'Your login code is 482913.',
  html: '<p>Your login code is <strong>482913</strong>.</p>',
  replyTo: 'support@dub.co',
  tags: [{ name: 'type', value: 'login' }],
};
const sent = await resend.emails.send(email);
assert.equal(sent.error, null, JSON.stringify(sent.error));
assert.ok(sent.data?.id, 'the send answered no id');
const saved = await resend.emails.get(sent.data.id);
assert.equal(saved.error, null, JSON.stringify(saved.error));
assert.equal(saved.data.id, sent.data.id);
assert.equal(saved.data.subject, email.subject);
assert.equal(saved.data.text, email.text);
assert.equal(saved.data.html, email.html);
assert.deepEqual(saved.data.to, email.to);
assert.deepEqual(saved.data.reply_to, [email.replyTo]);
assert.deepEqual(saved.data.tags, email.tags);
writeFileSync('last-email.json', JSON.stringify({ id: sent.data.id }) + '\n');
console.log(JSON.stringify({ sent: sent.data.id, last_event: saved.data.last_event }));

