import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { Resend } from 'resend';

if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const { id } = JSON.parse(readFileSync('last-email.json', 'utf8'));
const resend = new Resend(process.env.RESEND_API_KEY);
const saved = await resend.emails.get(id);
assert.equal(saved.error, null, JSON.stringify(saved.error));
assert.equal(saved.data.subject, 'Your Dub login code');
assert.equal(saved.data.last_event, 'delivered');
const listed = await resend.emails.list({ limit: 1 });
assert.equal(listed.error, null, JSON.stringify(listed.error));
assert.equal(listed.data.data[0]?.id, id);
console.log(JSON.stringify({ retained: id, last_event: saved.data.last_event }));
